use sha2::{Digest,Sha256};use std::fs;
fn main(){let mut h=Sha256::new();for f in ["Cargo.toml","Cargo.lock","build.rs","src/lib.rs","src/main.rs","src/frozen_kernel.rs","src/frozen_observe.rs","src/fast_extension.rs","src/frontiers.rs"]{println!("cargo:rerun-if-changed={f}");let b=fs::read(f).expect("Pinned source exists");h.update(f.as_bytes());h.update((b.len()as u64).to_le_bytes());h.update(b);}println!("cargo:rustc-env=FAST_REPLAY_ENGINE_HASH={:x}",h.finalize());println!("cargo:rustc-env=MEDIAN_ENGINE_HASH=d856d272d5c4f64d34836fd1f78c7e65f45897efd331c0a7ef813ab26d7c5778");}
